<?php
declare(strict_types=1);
require __DIR__.'/v10-lib.php';$token=(string)($_GET['token']??$_POST['token']??'');$msg='';$err='';$valid=null;if($token){$st=db()->prepare('SELECT r.*,u.email FROM v10_password_resets r JOIN users u ON u.id=r.user_id WHERE r.token_hash=? AND r.used_at IS NULL AND r.expires_at>NOW() LIMIT 1');$st->execute([hash('sha256',$token)]);$valid=$st->fetch();}if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){verify_csrf();try{if(!$valid)throw new RuntimeException('Invalid or expired token');$pass=(string)($_POST['password']??'');if(strlen($pass)<10)throw new RuntimeException('Password must be at least 10 characters');db()->beginTransaction();db()->prepare('UPDATE users SET password_hash=? WHERE id=? AND company_id=?')->execute([hash_password($pass),$valid['user_id'],$valid['company_id']]);db()->prepare('UPDATE v10_password_resets SET used_at=NOW() WHERE id=?')->execute([$valid['id']]);db()->commit();$msg='رمز تغییر کرد. اکنون وارد شوید. / Password changed.';$valid=null;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password</title><link rel="stylesheet" href="assets/app.css?v=10"></head><body class="auth-page"><main class="auth-card"><h1>رمز جدید / New password</h1><?php if($msg):?><div class="state success"><?=e($msg)?></div><a href="login.php">ورود / Login</a><?php elseif(!$valid):?><div class="state error">لینک نامعتبر یا منقضی است. / Invalid or expired link.</div><?php else:?><?php if($err):?><div class="state error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>رمز جدید / New password</label><input type="password" name="password" minlength="10" required><button class="btn primary">ذخیره / Save</button></form><?php endif;?></main></body></html>
